export const OFFICIAL_COVER_ASSETS={"covers.mjs":{"type":"application/javascript; charset=utf-8","bytes":2742,"sha256":"ff670a6c1d32dc7e6ef66950cae0ce8c8a10da2455f2ddde2f2254e13b9d384c","body":"export const PREFIX='/native-library/existing-new/20261110-official-covers-r1/';\nexport const OFFICIAL_COVERS=Object.freeze({\n multihot40_native:'/new-machines/catalog/multihot40-official-card.webp',\n balloon_native:PREFIX+'balloon_native.webp',\n jetx_native:PREFIX+'jetx_native.webp',\n});\n\n// Change only existing title artwork. The original card, dialog, focus, launch\n// anchor, account state and click handlers continue to belong to the Player.\nexport function installOfficialNewCovers({doc=document,win=window,covers=OFFICIAL_COVERS}={}){\n if(!['/','/games','/games/'].includes(win.location.pathname))return ()=>{};\n const loaded=new Map(),failed=new WeakSet();let stopped=false,frame=0;\n const selector='.portal-r9-grid > .portal-r9-card .portal-r9-cover[data-game],#portal-r9-game-sheet .portal-r9-sheet-cover[data-game]';\n function preload(url){\n  if(!loaded.has(url))loaded.set(url,new Promise(resolve=>{const image=new win.Image();image.onload=()=>resolve(true);image.onerror=()=>resolve(false);image.src=url;}));\n  return loaded.get(url);\n }\n async function update(wrap){\n  const id=wrap.dataset.game,url=Object.hasOwn(covers,id)?covers[id]:null;\n  if(!url||failed.has(wrap)||(wrap.dataset.zplayOfficialCover===id&&wrap.querySelector('img')?.getAttribute('src')===url))return;\n  if(!await preload(url)){failed.add(wrap);return;}\n  if(stopped||!wrap.isConnected||wrap.dataset.game!==id||(wrap.dataset.zplayOfficialCover===id&&wrap.querySelector('img')?.getAttribute('src')===url))return;\n  const old=wrap.querySelector('img'),fallback=wrap.querySelector('.portal-r9-generated-cover');\n  const image=old?old.cloneNode(false):doc.createElement('img');\n  image.alt=old?.alt||'';image.decoding='async';image.draggable=false;\n  image.addEventListener('error',()=>{\n   failed.add(wrap);delete wrap.dataset.zplayOfficialCover;\n   if(old)image.replaceWith(old);else image.remove();\n   if(fallback&&!fallback.isConnected)wrap.append(fallback);\n  },{once:true});\n  image.src=url;wrap.dataset.zplayOfficialCover=id;\n  if(old)old.replaceWith(image);else wrap.append(image);\n  fallback?.remove();\n }\n function render(){frame=0;if(stopped)return;for(const wrap of doc.querySelectorAll(selector))void update(wrap);}\n function schedule(){if(!stopped&&!frame)frame=win.requestAnimationFrame(render);}\n const observer=new win.MutationObserver(schedule);\n observer.observe(doc.documentElement,{subtree:true,childList:true,attributes:true,attributeFilter:['data-game','src']});\n schedule();\n return ()=>{stopped=true;observer.disconnect();win.cancelAnimationFrame(frame);};\n}\nif(typeof document!=='undefined'&&typeof window!=='undefined'){\n const key=Symbol.for('zplay.official-new-covers.r1');window[key]?.();window[key]=installOfficialNewCovers();\n}\n"},"covers.css":{"type":"text/css; charset=utf-8","bytes":288,"sha256":"d90d2d156b07148998f2f6fdaedf59c805c2c626ae1b9be1eaa4aac4571be1b6","body":"/* Retain the existing card/sheet geometry. Fit the full official title card\n   within it, including the current game's 16:11 card container. */\n.portal-r9-cover[data-zplay-official-cover] > img,\n.portal-r9-sheet-cover[data-zplay-official-cover] > img { object-fit: contain !important; }\n"},"balloon_native.webp":{"type":"image/webp","bytes":23274,"sha256":"94351cbba78b0dec0bf02d86669f7044142bd99b819cfe4bb10f72b93927f5a2","body":"","encoding":"base64"},"jetx_native.webp":{"type":"image/webp","bytes":13680,"sha256":"8e8731237f6bd790320c1d3629fe5603514569bae7c5970e9b95cba0321f3199","body":"","encoding":"base64"}};
